    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_wbm_64b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(wbm_64b_ar_slot_subtractive_in_valid), .wr_ready(wbm_64b_ar_slot_subtractive_in_ready), .wr_data(wbm_64b_ar),
        .rd_valid(wbm_64b_ar_slot_subtractive_valid), .rd_ready(wbm_64b_ar_slot_subtractive_ready), .rd_data(wbm_64b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );
    assign cpu_64b_ar_slot_subtractive_in_valid = cpu_64b_ar_to_subtractive && cpu_64b_arvalid;
    gaxi_skid_buffer #(.DEPTH(2), .DATA_WIDTH($bits(axi4_ar_t))) u_cpu_64b_ar_slot_subtractive (
        .axi_aclk(aclk), .axi_aresetn(aresetn),
        .wr_valid(cpu_64b_ar_slot_subtractive_in_valid), .wr_ready(cpu_64b_ar_slot_subtractive_in_ready), .wr_data(cpu_64b_ar),
        .rd_valid(cpu_64b_ar_slot_subtractive_valid), .rd_ready(cpu_64b_ar_slot_subtractive_ready), .rd_data(cpu_64b_ar_slot_subtractive),
        /* verilator lint_off PINCONNECTEMPTY */
        .count(), .rd_count()
        /* verilator lint_on PINCONNECTEMPTY */
    );

    // ---- AR arbiter for subtractive: round-robin, lock until handshake ----
    logic [1:0] subtractive_ar_arb_req;
    assign subtractive_ar_arb_req = {cpu_64b_ar_slot_subtractive_valid, wbm_64b_ar_slot_subtractive_valid};
    logic [0:0] subtractive_ar_arb_lock, subtractive_ar_arb_rr;
    logic subtractive_ar_arb_locked;
    wire [0:0] subtractive_ar_arb_pick = (subtractive_ar_arb_rr == 1'd0) ? (subtractive_ar_arb_req[0] ? 1'd0 : 1'd1) : 
        subtractive_ar_arb_req[1] ? 1'd1 : 1'd0;
    wire subtractive_ar_arb_gnt_valid = subtractive_ar_arb_locked || (|subtractive_ar_arb_req);
    wire [0:0] subtractive_ar_arb_gnt = subtractive_ar_arb_locked ? subtractive_ar_arb_lock : subtractive_ar_arb_pick;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            subtractive_ar_arb_lock   <= '0;
            subtractive_ar_arb_rr     <= '0;
            subtractive_ar_arb_locked <= 1'b0;
        end else begin
            if (subtractive_axi_arvalid && subtractive_axi_arready) begin
                subtractive_ar_arb_locked <= 1'b0;
                subtractive_ar_arb_rr <= (subtractive_ar_arb_gnt == 1'd1) ? 1'd0 : subtractive_ar_arb_gnt + 1'b1;
            end else if (subtractive_axi_arvalid) begin
                subtractive_ar_arb_lock   <= subtractive_ar_arb_gnt;
                subtractive_ar_arb_locked <= 1'b1;
            end
        end
    )
    wire wbm_64b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 1'd0) && subtractive_ar_arb_req[0];
    wire cpu_64b_ar_gnt_subtractive = subtractive_ar_arb_gnt_valid && (subtractive_ar_arb_gnt == 1'd1) && subtractive_ar_arb_req[1];
    assign wbm_64b_ar_slot_subtractive_ready = wbm_64b_ar_gnt_subtractive && subtractive_axi_arready;
    assign cpu_64b_ar_slot_subtractive_ready = cpu_64b_ar_gnt_subtractive && subtractive_axi_arready;

    // AR channel (arbitrated mux across reading masters)
    assign subtractive_axi_arid = (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.id : '0) |
        (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.id : '0);
    assign subtractive_axi_araddr = (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.addr : '0) |
        (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.addr : '0);
    assign subtractive_axi_arlen = (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.len : '0) |
        (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.len : '0);
    assign subtractive_axi_arsize = (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.size : '0) |
        (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.size : '0);
    assign subtractive_axi_arburst = (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.burst : '0) |
        (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.burst : '0);
    assign subtractive_axi_arlock = (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.lock : '0) |
        (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.lock : '0);
    assign subtractive_axi_arcache = (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.cache : '0) |
        (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.cache : '0);
    assign subtractive_axi_arprot = (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.prot : '0) |
        (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.prot : '0);
    assign subtractive_axi_arqos = (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.qos : '0) |
        (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.qos : '0);
    assign subtractive_axi_arregion = (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.region : '0) |
        (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.region : '0);
    assign subtractive_axi_aruser = (wbm_64b_ar_gnt_subtractive ? wbm_64b_ar_slot_subtractive.user : '0) |
        (cpu_64b_ar_gnt_subtractive ? cpu_64b_ar_slot_subtractive.user : '0);
    assign subtractive_axi_arvalid = wbm_64b_ar_gnt_subtractive || cpu_64b_ar_gnt_subtractive;

    // Rready (slave -> the master whose response arbiter granted it)
    assign subtractive_axi_rready = (wbm_64b_r_rgnt_subtractive ? wbm_64b_rready : '0) |
        (cpu_64b_r_rgnt_subtractive ? cpu_64b_rready : '0);

    // Bridge ID (reads) — the granted master's id
    assign subtractive_axi_bridge_id_ar = (wbm_64b_ar_gnt_subtractive ? wbm_bridge_id_ar : '0) |
        (cpu_64b_ar_gnt_subtractive ? cpu_bridge_id_ar : '0);


    // ================================================================
    // W destination FIFOs (per master width-path)
    // ================================================================
    // wbm 32b path -> wbp (16 deep: max_outstanding)
    logic [0:0] wbm_32b_wdest_mem [16];
    logic [4:0] wbm_32b_wdest_wptr, wbm_32b_wdest_rptr;
    wire [0:0] wbm_32b_wdest_enc = 1'd0;
    wire wbm_32b_wdest_push = wbm_32b_awvalid && wbm_32b_awready;
    wire wbm_32b_wdest_pop  = wbm_32b_wvalid && wbm_32b_wready && wbm_32b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            wbm_32b_wdest_wptr <= '0;
            wbm_32b_wdest_rptr <= '0;
        end else begin
            if (wbm_32b_wdest_push) begin
                wbm_32b_wdest_mem[wbm_32b_wdest_wptr[3:0]] <= wbm_32b_wdest_enc;
                wbm_32b_wdest_wptr <= wbm_32b_wdest_wptr + 1'b1;
            end
            if (wbm_32b_wdest_pop) begin
                wbm_32b_wdest_rptr <= wbm_32b_wdest_rptr + 1'b1;
            end
        end
    )
    wire wbm_32b_wdest_valid = (wbm_32b_wdest_wptr != wbm_32b_wdest_rptr);
    wire [0:0] wbm_32b_wdest_head = wbm_32b_wdest_mem[wbm_32b_wdest_rptr[3:0]];
    assign wbm_32b_w_to_wbp = wbm_32b_wdest_valid && (wbm_32b_wdest_head == 1'd0);

    // wbm 64b path -> mem, subtractive (16 deep: max_outstanding)
    logic [0:0] wbm_64b_wdest_mem [16];
    logic [4:0] wbm_64b_wdest_wptr, wbm_64b_wdest_rptr;
    wire [0:0] wbm_64b_wdest_enc = wbm_64b_aw_to_subtractive ? 1'd1 : 1'd0;
    wire wbm_64b_wdest_push = wbm_64b_awvalid && wbm_64b_awready;
    wire wbm_64b_wdest_pop  = wbm_64b_wvalid && wbm_64b_wready && wbm_64b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            wbm_64b_wdest_wptr <= '0;
            wbm_64b_wdest_rptr <= '0;
        end else begin
            if (wbm_64b_wdest_push) begin
                wbm_64b_wdest_mem[wbm_64b_wdest_wptr[3:0]] <= wbm_64b_wdest_enc;
                wbm_64b_wdest_wptr <= wbm_64b_wdest_wptr + 1'b1;
            end
            if (wbm_64b_wdest_pop) begin
                wbm_64b_wdest_rptr <= wbm_64b_wdest_rptr + 1'b1;
            end
        end
    )
    wire wbm_64b_wdest_valid = (wbm_64b_wdest_wptr != wbm_64b_wdest_rptr);
    wire [0:0] wbm_64b_wdest_head = wbm_64b_wdest_mem[wbm_64b_wdest_rptr[3:0]];
    assign wbm_64b_w_to_mem = wbm_64b_wdest_valid && (wbm_64b_wdest_head == 1'd0);
    assign wbm_64b_w_to_subtractive = wbm_64b_wdest_valid && (wbm_64b_wdest_head == 1'd1);

    // cpu 32b path -> wbp (16 deep: max_outstanding)
    logic [0:0] cpu_32b_wdest_mem [16];
    logic [4:0] cpu_32b_wdest_wptr, cpu_32b_wdest_rptr;
    wire [0:0] cpu_32b_wdest_enc = 1'd0;
    wire cpu_32b_wdest_push = cpu_32b_awvalid && cpu_32b_awready;
    wire cpu_32b_wdest_pop  = cpu_32b_wvalid && cpu_32b_wready && cpu_32b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            cpu_32b_wdest_wptr <= '0;
            cpu_32b_wdest_rptr <= '0;
        end else begin
            if (cpu_32b_wdest_push) begin
                cpu_32b_wdest_mem[cpu_32b_wdest_wptr[3:0]] <= cpu_32b_wdest_enc;
                cpu_32b_wdest_wptr <= cpu_32b_wdest_wptr + 1'b1;
            end
            if (cpu_32b_wdest_pop) begin
                cpu_32b_wdest_rptr <= cpu_32b_wdest_rptr + 1'b1;
            end
        end
    )
    wire cpu_32b_wdest_valid = (cpu_32b_wdest_wptr != cpu_32b_wdest_rptr);
    wire [0:0] cpu_32b_wdest_head = cpu_32b_wdest_mem[cpu_32b_wdest_rptr[3:0]];
    assign cpu_32b_w_to_wbp = cpu_32b_wdest_valid && (cpu_32b_wdest_head == 1'd0);

    // cpu 64b path -> mem, subtractive (16 deep: max_outstanding)
    logic [0:0] cpu_64b_wdest_mem [16];
    logic [4:0] cpu_64b_wdest_wptr, cpu_64b_wdest_rptr;
    wire [0:0] cpu_64b_wdest_enc = cpu_64b_aw_to_subtractive ? 1'd1 : 1'd0;
    wire cpu_64b_wdest_push = cpu_64b_awvalid && cpu_64b_awready;
    wire cpu_64b_wdest_pop  = cpu_64b_wvalid && cpu_64b_wready && cpu_64b_w.last;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            cpu_64b_wdest_wptr <= '0;
            cpu_64b_wdest_rptr <= '0;
        end else begin
            if (cpu_64b_wdest_push) begin
                cpu_64b_wdest_mem[cpu_64b_wdest_wptr[3:0]] <= cpu_64b_wdest_enc;
                cpu_64b_wdest_wptr <= cpu_64b_wdest_wptr + 1'b1;
            end
            if (cpu_64b_wdest_pop) begin
                cpu_64b_wdest_rptr <= cpu_64b_wdest_rptr + 1'b1;
            end
        end
    )
    wire cpu_64b_wdest_valid = (cpu_64b_wdest_wptr != cpu_64b_wdest_rptr);
    wire [0:0] cpu_64b_wdest_head = cpu_64b_wdest_mem[cpu_64b_wdest_rptr[3:0]];
    assign cpu_64b_w_to_mem = cpu_64b_wdest_valid && (cpu_64b_wdest_head == 1'd0);
    assign cpu_64b_w_to_subtractive = cpu_64b_wdest_valid && (cpu_64b_wdest_head == 1'd1);

    // ================================================================
    // Response MUXes (OR together all slave responses)
    // ================================================================

    // Master: wbm, Width path: 32b
    assign wbm_32b_awready = 
        (wbm_32b_aw_gnt_wbp ? wbp_axi_awready : '0);

    assign wbm_32b_wready = 
        (wbm_32b_w_sel_wbp ? wbp_axi_wready : '0);

    assign wbm_32b_b.id = 
        (wbm_32b_b_rgnt_wbp ? wbp_axi_bid : '0);

    assign wbm_32b_b.resp = 
        (wbm_32b_b_rgnt_wbp ? wbp_axi_bresp : '0);

    assign wbm_32b_b.user = 
        (wbm_32b_b_rgnt_wbp ? wbp_axi_buser : '0);

    assign wbm_32b_bvalid = 
        (wbm_32b_b_rgnt_wbp ? wbp_axi_bvalid : '0);

    assign wbm_32b_arready = 
        (wbm_32b_ar_gnt_wbp ? wbp_axi_arready : '0);

    assign wbm_32b_r.id = 
        (wbm_32b_r_rgnt_wbp ? wbp_axi_rid : '0);

    assign wbm_32b_r.data = 
        (wbm_32b_r_rgnt_wbp ? wbp_axi_rdata : 32'b0);

    assign wbm_32b_r.resp = 
        (wbm_32b_r_rgnt_wbp ? wbp_axi_rresp : '0);

    assign wbm_32b_r.last = 
        (wbm_32b_r_rgnt_wbp ? wbp_axi_rlast : '0);

    assign wbm_32b_r.user = 
        (wbm_32b_r_rgnt_wbp ? wbp_axi_ruser : '0);

    assign wbm_32b_rvalid = 
        (wbm_32b_r_rgnt_wbp ? wbp_axi_rvalid : '0);


    // Master: wbm, Width path: 64b
    assign wbm_64b_awready = 
        ((wbm_64b_aw_to_mem && !wbm_64b_aw_hold_mem) ? wbm_64b_aw_slot_mem_in_ready : '0) |
        ((wbm_64b_aw_to_subtractive && !wbm_64b_aw_hold_subtractive) ? wbm_64b_aw_slot_subtractive_in_ready : '0);

    assign wbm_64b_wready = 
        (wbm_64b_w_sel_mem ? mem_axi_wready : '0) |
        (wbm_64b_w_sel_subtractive ? subtractive_axi_wready : '0);

    assign wbm_64b_b.id = 
        (wbm_64b_b_rgnt_mem ? mem_axi_bid : '0) |
        (wbm_64b_b_rgnt_subtractive ? subtractive_axi_bid : '0);

    assign wbm_64b_b.resp = 
        (wbm_64b_b_rgnt_mem ? mem_axi_bresp : '0) |
        (wbm_64b_b_rgnt_subtractive ? subtractive_axi_bresp : '0);

    assign wbm_64b_b.user = 
        (wbm_64b_b_rgnt_mem ? mem_axi_buser : '0) |
        (wbm_64b_b_rgnt_subtractive ? subtractive_axi_buser : '0);

    assign wbm_64b_bvalid = 
        (wbm_64b_b_rgnt_mem ? mem_axi_bvalid : '0) |
        (wbm_64b_b_rgnt_subtractive ? subtractive_axi_bvalid : '0);

    assign wbm_64b_arready = 
        ((wbm_64b_ar_to_mem) ? wbm_64b_ar_slot_mem_in_ready : '0) |
        ((wbm_64b_ar_to_subtractive) ? wbm_64b_ar_slot_subtractive_in_ready : '0);

    assign wbm_64b_r.id = 
        (wbm_64b_r_rgnt_mem ? mem_axi_rid : '0) |
        (wbm_64b_r_rgnt_subtractive ? subtractive_axi_rid : '0);

    assign wbm_64b_r.data = 
        (wbm_64b_r_rgnt_mem ? mem_axi_rdata : 64'b0) |
        (wbm_64b_r_rgnt_subtractive ? subtractive_axi_rdata : 64'b0);

    assign wbm_64b_r.resp = 
        (wbm_64b_r_rgnt_mem ? mem_axi_rresp : '0) |
        (wbm_64b_r_rgnt_subtractive ? subtractive_axi_rresp : '0);

    assign wbm_64b_r.last = 
        (wbm_64b_r_rgnt_mem ? mem_axi_rlast : '0) |
        (wbm_64b_r_rgnt_subtractive ? subtractive_axi_rlast : '0);

    assign wbm_64b_r.user = 
        (wbm_64b_r_rgnt_mem ? mem_axi_ruser : '0) |
        (wbm_64b_r_rgnt_subtractive ? subtractive_axi_ruser : '0);

    assign wbm_64b_rvalid = 
        (wbm_64b_r_rgnt_mem ? mem_axi_rvalid : '0) |
        (wbm_64b_r_rgnt_subtractive ? subtractive_axi_rvalid : '0);


    // Master: cpu, Width path: 32b
    assign cpu_32b_awready = 
        (cpu_32b_aw_gnt_wbp ? wbp_axi_awready : '0);

    assign cpu_32b_wready = 
        (cpu_32b_w_sel_wbp ? wbp_axi_wready : '0);

    assign cpu_32b_b.id = 
        (cpu_32b_b_rgnt_wbp ? wbp_axi_bid : '0);

    assign cpu_32b_b.resp = 
        (cpu_32b_b_rgnt_wbp ? wbp_axi_bresp : '0);

    assign cpu_32b_b.user = 
        (cpu_32b_b_rgnt_wbp ? wbp_axi_buser : '0);

    assign cpu_32b_bvalid = 
        (cpu_32b_b_rgnt_wbp ? wbp_axi_bvalid : '0);

    assign cpu_32b_arready = 
        (cpu_32b_ar_gnt_wbp ? wbp_axi_arready : '0);

    assign cpu_32b_r.id = 
        (cpu_32b_r_rgnt_wbp ? wbp_axi_rid : '0);

    assign cpu_32b_r.data = 
        (cpu_32b_r_rgnt_wbp ? wbp_axi_rdata : 32'b0);

    assign cpu_32b_r.resp = 
        (cpu_32b_r_rgnt_wbp ? wbp_axi_rresp : '0);

    assign cpu_32b_r.last = 
        (cpu_32b_r_rgnt_wbp ? wbp_axi_rlast : '0);

    assign cpu_32b_r.user = 
        (cpu_32b_r_rgnt_wbp ? wbp_axi_ruser : '0);

    assign cpu_32b_rvalid = 
        (cpu_32b_r_rgnt_wbp ? wbp_axi_rvalid : '0);


    // Master: cpu, Width path: 64b
    assign cpu_64b_awready = 
        ((cpu_64b_aw_to_mem && !cpu_64b_aw_hold_mem) ? cpu_64b_aw_slot_mem_in_ready : '0) |
        ((cpu_64b_aw_to_subtractive && !cpu_64b_aw_hold_subtractive) ? cpu_64b_aw_slot_subtractive_in_ready : '0);

    assign cpu_64b_wready = 
        (cpu_64b_w_sel_mem ? mem_axi_wready : '0) |
        (cpu_64b_w_sel_subtractive ? subtractive_axi_wready : '0);

    assign cpu_64b_b.id = 
        (cpu_64b_b_rgnt_mem ? mem_axi_bid : '0) |
        (cpu_64b_b_rgnt_subtractive ? subtractive_axi_bid : '0);

    assign cpu_64b_b.resp = 
        (cpu_64b_b_rgnt_mem ? mem_axi_bresp : '0) |
        (cpu_64b_b_rgnt_subtractive ? subtractive_axi_bresp : '0);

    assign cpu_64b_b.user = 
        (cpu_64b_b_rgnt_mem ? mem_axi_buser : '0) |
        (cpu_64b_b_rgnt_subtractive ? subtractive_axi_buser : '0);

    assign cpu_64b_bvalid = 
        (cpu_64b_b_rgnt_mem ? mem_axi_bvalid : '0) |
        (cpu_64b_b_rgnt_subtractive ? subtractive_axi_bvalid : '0);

    assign cpu_64b_arready = 
        ((cpu_64b_ar_to_mem) ? cpu_64b_ar_slot_mem_in_ready : '0) |
        ((cpu_64b_ar_to_subtractive) ? cpu_64b_ar_slot_subtractive_in_ready : '0);

    assign cpu_64b_r.id = 
        (cpu_64b_r_rgnt_mem ? mem_axi_rid : '0) |
        (cpu_64b_r_rgnt_subtractive ? subtractive_axi_rid : '0);

    assign cpu_64b_r.data = 
        (cpu_64b_r_rgnt_mem ? mem_axi_rdata : 64'b0) |
        (cpu_64b_r_rgnt_subtractive ? subtractive_axi_rdata : 64'b0);

    assign cpu_64b_r.resp = 
        (cpu_64b_r_rgnt_mem ? mem_axi_rresp : '0) |
        (cpu_64b_r_rgnt_subtractive ? subtractive_axi_rresp : '0);

    assign cpu_64b_r.last = 
        (cpu_64b_r_rgnt_mem ? mem_axi_rlast : '0) |
        (cpu_64b_r_rgnt_subtractive ? subtractive_axi_rlast : '0);

    assign cpu_64b_r.user = 
        (cpu_64b_r_rgnt_mem ? mem_axi_ruser : '0) |
        (cpu_64b_r_rgnt_subtractive ? subtractive_axi_ruser : '0);

    assign cpu_64b_rvalid = 
        (cpu_64b_r_rgnt_mem ? mem_axi_rvalid : '0) |
        (cpu_64b_r_rgnt_subtractive ? subtractive_axi_rvalid : '0);


endmodule : bridge_2x2_wb4_xbar
